import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import { Activity, Gauge, Zap, Thermometer } from 'lucide-react';

ChartJS.register(ArcElement, Tooltip, Legend);

const StatusChart = ({ running = 0, idle = 0, maintenance = 0 }) => {
  const total = running + idle + maintenance;

  const data = {
    labels: ['Running', 'Idle', 'Under Maintenance'],
    datasets: [
      {
        data: [running, idle, maintenance],
        backgroundColor: [
          'rgba(5, 150, 105, 0.95)',
          'rgba(217, 119, 6, 0.95)',
          'rgba(225, 29, 72, 0.95)',
        ],
        borderColor: ['#ffffff', '#ffffff', '#ffffff'],
        borderWidth: 3,
        hoverOffset: 10,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: '#0F172A',
          font: {
            family: "'Plus Jakarta Sans', sans-serif",
            size: 13,
            weight: '800',
          },
          padding: 16,
          usePointStyle: true,
          pointStyle: 'circle',
        },
      },
      tooltip: {
        backgroundColor: '#0F172A',
        titleColor: '#FFFFFF',
        bodyColor: '#E2E8F0',
        borderColor: '#E2E8F0',
        borderWidth: 1,
        padding: 12,
      },
    },
    cutout: '62%', // Thicker, bigger donut ring!
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', height: '100%' }}>
      {/* BIG Prominent Donut Chart Canvas */}
      <div style={{ height: '290px', width: '100%', position: 'relative' }}>
        <Doughnut data={data} options={options} />
        {/* Center Donut Metric Counter */}
        <div
          style={{
            position: 'absolute',
            top: '38%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            pointerEvents: 'none',
          }}
        >
          <div style={{ fontSize: '2.8rem', fontWeight: '900', color: '#0F172A', lineHeight: 1 }}>{total}</div>
          <div style={{ fontSize: '0.8rem', fontWeight: '800', color: '#334155', marginTop: '4px', letterSpacing: '0.5px' }}>
            TOTAL LOOMS
          </div>
        </div>
      </div>

      {/* Filled Free Space Widget: Live Fleet Operational Summary */}
      <div
        style={{
          background: 'var(--bg-primary)',
          border: '1px solid var(--border-subtle)',
          borderRadius: 'var(--radius-sm)',
          padding: '0.85rem 1rem',
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: '0.75rem',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Gauge size={16} style={{ color: 'var(--status-running)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: '#334155', fontWeight: '800' }}>FLEET OEE</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A' }}>96.4%</div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Activity size={16} style={{ color: 'var(--accent-primary)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: '#334155', fontWeight: '800' }}>OUTPUT RATE</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A' }}>1,485 M/hr</div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Zap size={16} style={{ color: 'var(--status-idle)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: '#334155', fontWeight: '800' }}>ACTIVE SENSORS</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A' }}>136 IoT Feeds</div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Thermometer size={16} style={{ color: 'var(--status-maintenance)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: '#334155', fontWeight: '800' }}>AVG TEMP</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A' }}>54.2°C</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StatusChart;
